// Kapi alarmi: kapi acilinca buzzer oter ve kirmizi LED yanar.
// Manyetik kapi sensoru (reed switch) D27 ile GND arasinda.

// --- Pinler (baglantilarla ayni) ---
const int REED_PIN = 27;    // D27: kapi sensoru
const int LED_PIN = 26;     // D26: kirmizi LED (220 ohm direncle)
const int BUZZER_PIN = 25;  // D25: buzzer +

// --- Ayarlar ---
// Cogu kapi sensorunde (MC-38) miknatis yakinken kontak kapalidir.
// Kapi kapali -> pin LOW, kapi acik -> pin HIGH.
// Sensorun ters calisiyorsa (NC tipi) bunu LOW yap.
const int KAPI_ACIK_SEVIYE = HIGH;
const int BIP_FREKANS = 2000;      // Hz. Buzzer sesinin inceligi.
const unsigned long BIP_SURE = 200;    // ms. Bir bip ne kadar surer.
const unsigned long BIP_ARA = 300;     // ms. Iki bip arasi sessizlik.
const unsigned long KARARLILIK = 50;   // ms. Kontak titresimini yok sayma suresi.

// --- Durum ---
bool kapiAcik = false;
int sonOkuma = -1;
unsigned long sonDegisim = 0;
unsigned long sonBip = 0;

void setup() {
  Serial.begin(115200);
  // Ic pull-up: kontak acikken pin HIGH, kapaliyken GND'ye cekilir.
  pinMode(REED_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
  noTone(BUZZER_PIN);
  Serial.println("Kapi alarmi hazir.");
}

void loop() {
  unsigned long simdi = millis();
  int okuma = digitalRead(REED_PIN);

  // Okuma degisince sayaci sifirla; KARARLILIK suresi boyunca ayni kalirsa kabul et.
  if (okuma != sonOkuma) {
    sonOkuma = okuma;
    sonDegisim = simdi;
  }
  bool yeniDurum = (sonOkuma == KAPI_ACIK_SEVIYE);
  if (simdi - sonDegisim >= KARARLILIK && yeniDurum != kapiAcik) {
    kapiAcik = yeniDurum;
    if (kapiAcik) {
      Serial.println("Kapi ACILDI");
      digitalWrite(LED_PIN, HIGH);
      sonBip = simdi - (BIP_SURE + BIP_ARA);  // ilk bip hemen calsin
    } else {
      Serial.println("Kapi kapandi");
      digitalWrite(LED_PIN, LOW);
      noTone(BUZZER_PIN);
    }
  }

  // Kapi acik kaldikca kesik kesik bip.
  if (kapiAcik && simdi - sonBip >= BIP_SURE + BIP_ARA) {
    tone(BUZZER_PIN, BIP_FREKANS, BIP_SURE);
    sonBip = simdi;
  }
}
